CREATE POLICY clinical_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='clinical-originals' AND public.has_clinic_role(((storage.foldername(name))[1])::uuid,true)); CREATE POLICY clinical_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='clinical-originals' AND public.has_clinic_role(((storage.foldername(name))[1])::uuid,true));